content:
{
  "code": ":root {
  --color-bg: #ffffff;
  --color-text-primary: #1a1a1a;
  --color-text-secondary: #666666;
  --color-border: #e5e5e5;
  --color-surface-subtle: #f7f7f7;
  --color-highlight: #000000;
  --color-highlight-text: #ffffff;

  --font-stack-korean: 'Apple SD Gothic Neo', 'Malgun Gothic', 'Noto Sans KR', sans-serif;
  --font-stack-latin: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-pill: 999px;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  font-family: var(--font-stack-korean), var(--font-stack-latin);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#app {
  max-width: 430px;
  margin: 0 auto;
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  position: relative;
}

.header {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-md) 0;
  margin-bottom: var(--space-lg);
}

#page-title {
  font-size: 20px;
  font-weight: 700;
  margin: 0;
  color: var(--color-text-primary);
}

.destination-pills {
  display: flex;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
  padding: 0 var(--space-sm);
}

.pill {
  flex: 1;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-pill);
  border: 1px solid var(--color-border);
  background-color: var(--color-bg);
  color: var(--color-text-secondary);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
}

.pill.active {
  background-color: var(--color-highlight);
  color: var(--color-highlight-text);
  border-color: var(--color-highlight);
}

#itinerary-list {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
  padding-bottom: var(--space-xl);
}

.day-heading {
  font-size: 16px;
  font-weight: 600;
  color: var(--color-text-primary);
  margin: var(--space-md) 0 var(--space-sm);
  padding-left: var(--space-sm);
}

.place-row {
  display: flex;
  align-items: center;
  background-color: var(--color-surface-subtle);
  border-radius: var(--radius-md);
  padding: var(--space-sm);
  gap: var(--space-sm);
}

.checkbox-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}

.checkbox-wrapper input[type="checkbox"] {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: var(--color-highlight);
}

.place-media {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  flex-shrink: 0;
  background-color: var(--color-border);
}

.place-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.place-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.place-name {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.place-meta {
  font-size: 12px;
  color: var(--color-text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.reorder-handle {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: grab;
  padding: 0;
  flex-shrink: 0;
}

.reorder-handle img {
  width: 16px;
  height: 16px;
  opacity: 0.5;
  pointer-events: none;
}

.action-footer {
  padding: var(--space-md) 0;
  border-top: 1px solid var(--color-border);
  margin-top: auto;
}

.btn-primary {
  width: 100%;
  padding: var(--space-md);
  background-color: var(--color-highlight);
  color: var(--color-highlight-text);
  border: none;
  border-radius: var(--radius-md);
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.btn-primary:disabled {
  background-color: var(--color-border);
  color: var(--color-text-secondary);
  cursor: not-allowed;
}"
}
